def is_derived_from(derived, based):
    """returns True, if derived is derived from based, False otherwise"""
    return is_base_and_derived(based, derived)

def is_derived_from_any(derived, based_list):
    """returns True, if any of the bases in the based_list is a base of
    the derived, False otherwise"""
    for based in based_list:
        if is_derived_from(derived, based):
            return True
    return False

def is_derived_from_all(derived, based_list):
    """returns True, if all of the bases in the based_list is a base of
    the derived, False otherwise"""
    for based in based_list:
        if not is_derived_from(derived, based):
            return False
    return True

def is_derived_from_none(derived, based_list):
    """returns True, if none of the bases in the based_list is a base of
    the derived, False otherwise"""
    for based in based_list:
        if is_derived_from(derived, based):
            return False
    return True

